// Generates CSS custom properties and a typed token map from tokens/tokens.json,
// the token file exported from the Claude Design system. tokens.json stays the
// source of truth: edit it (or re-export it), never the generated files.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const source = JSON.parse(readFileSync(join(root, 'tokens/tokens.json'), 'utf8'));

const families = ['color', 'effect', 'radius', 'shadow', 'spacing', 'structure', 'tracking', 'motion'];
const flat = new Map();
for (const family of families) {
  for (const token of source[family]?.tokens ?? []) flat.set(token.name, token.value);
}
for (const [name, value] of Object.entries(source.type?.families ?? {})) flat.set(`font-${name}`, value);
for (const group of source.type?.groups ?? []) {
  for (const style of group.styles ?? []) {
    const role = style.name.replace(/^w-text-/, '');
    flat.set(`type-${role}`, style.fontSize);
    flat.set(`leading-${role}`, style.lineHeight);
    flat.set(`weight-${role}`, String(style.fontWeight));
    if (style.letterSpacing) flat.set(`tracking-${role}`, style.letterSpacing);
  }
}

// "{info}" references another token.
const resolve = (value) => String(value).replace(/\{([a-z0-9-]+)\}/g, (_, ref) => `var(--${ref})`);

const lines = [...flat].map(([name, value]) => `  --${name}: ${resolve(value)};`);
const header = `/* Generated by scripts/build-tokens.mjs from tokens.json (${source.name} v${source.version}). Do not edit. */\n`;
const css = `${header}:root {\n${lines.join('\n')}\n}\n`;

const ts = `${header.replace('/*', '//').replace(' */', '')}export const tokens = ${JSON.stringify(Object.fromEntries(flat), null, 2)} as const;\n\nexport type TokenName = keyof typeof tokens;\n\n/** A CSS var() reference to a token, for use in component styles. */\nexport const token = (name: TokenName): string => \`var(--\${name})\`;\n`;

mkdirSync(join(root, 'src/generated'), { recursive: true });
mkdirSync(join(root, 'dist'), { recursive: true });
writeFileSync(join(root, 'src/generated/tokens.ts'), ts);
writeFileSync(join(root, 'dist/tokens.css'), css);
console.log(`ui-kit: wrote ${flat.size} tokens`);
